// 16-nov: TikTok desde G54. Recibe un post ya aprobado y arma el envío a TikTok.
// Modo "borrador" (por defecto): llega a la bandeja de TikTok de la empresa y una persona lo publica desde la app.
// No necesita la auditoría de TikTok. Modo "directo": publica solo; necesita la app auditada por TikTok.
// Entrada: { company_id, post_id, texto, titulo?, hashtags?, imagenes?: [url], imagen_url?, video_url?, modo? }
const b = $json.body || $json;
const errores = [];
const companyId = Number(b.company_id);
if (!companyId) errores.push('Falta company_id');
const modo = b.modo === 'directo' ? 'directo' : 'borrador';
const video = String(b.video_url || '').trim();
let imagenes = Array.isArray(b.imagenes) ? b.imagenes.filter(Boolean).map(String) : [];
if (!imagenes.length && b.imagen_url) imagenes = [String(b.imagen_url)];
if (!video && !imagenes.length) errores.push('Falta video_url o una imagen');
if (imagenes.length > 35) imagenes = imagenes.slice(0, 35); // TikTok acepta hasta 35 fotos
for (const u of [video, ...imagenes].filter(Boolean)) {
  if (!/^https:\/\//i.test(u)) errores.push('La URL tiene que ser https: ' + u);
}
// TikTok cuenta en unidades UTF-16 (como .length de JavaScript): título 90, descripción 4000.
const corta = (s, n) => { s = String(s || '').trim(); return s.length <= n ? s : s.slice(0, n - 1).trimEnd() + '…'; };
const hashtags = String(b.hashtags || '').trim();
const texto = String(b.texto || '').trim();
if (!texto && !hashtags) errores.push('Falta el texto del post');
const descripcion = corta([texto, hashtags].filter(Boolean).join('\n\n'), 4000);
const titulo = corta(b.titulo || texto.split('\n')[0], 90);

const API = 'https://open.tiktokapis.com/v2/post/publish';
let url, cuerpo;
if (video) {
  url = modo === 'borrador' ? `${API}/inbox/video/init/` : `${API}/video/init/`;
  cuerpo = { source_info: { source: 'PULL_FROM_URL', video_url: video } };
  if (modo === 'directo') cuerpo.post_info = { title: corta(descripcion, 2200) }; // en video el texto va en title (máx. 2200)
} else {
  url = `${API}/content/init/`;
  cuerpo = {
    media_type: 'PHOTO',
    post_mode: modo === 'borrador' ? 'MEDIA_UPLOAD' : 'DIRECT_POST',
    post_info: { title: titulo, description: descripcion },
    source_info: { source: 'PULL_FROM_URL', photo_images: imagenes, photo_cover_index: 0 },
  };
}
return [{ json: { ok: errores.length === 0, errores, company_id: companyId, post_id: b.post_id || null, modo, tipo: video ? 'video' : 'fotos', url, cuerpo } }];

// 16-nov: envía a TikTok con el token de la empresa que guarda G54 y sigue el estado hasta saber si llegó.
// No reintenta el envío: un reintento puede duplicar el post. Solo consulta el estado (eso sí es seguro).
const p = $('🔧 Preparar Publicación TikTok').first().json;
const t = $('🔑 G54: Token TikTok de la empresa').first().json || {};
const tok = (t.data || t);
const fin = (ok, extra) => [{ json: { ok, company_id: p.company_id, post_id: p.post_id, modo: p.modo, tipo: p.tipo, ...extra } }];
if (!p.ok) return fin(false, { motivo: p.errores.join('; ') });
if (!tok.access_token || tok.connected === false) return fin(false, { motivo: 'La empresa no tiene TikTok conectado en G54' });

const H = { Authorization: 'Bearer ' + tok.access_token, 'Content-Type': 'application/json; charset=UTF-8' };
const llamar = async (url, body) => {
  const r = await this.helpers.httpRequest({ method: 'POST', url, headers: H, body, json: true, timeout: 20000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  const j = r.body || {};
  const code = (j.error && j.error.code) || (r.statusCode >= 400 ? 'http_' + r.statusCode : 'ok');
  return { status: r.statusCode, code, mensaje: (j.error && j.error.message) || '', data: j.data || {} };
};
const cuerpo = JSON.parse(JSON.stringify(p.cuerpo));

// Modo directo: TikTok exige consultar antes qué privacidad permite la cuenta y usar una de esas.
if (p.modo === 'directo') {
  const ci = await llamar('https://open.tiktokapis.com/v2/post/publish/creator_info/query/', {});
  if (ci.code !== 'ok') return fin(false, { motivo: `TikTok (consulta de la cuenta): ${ci.code} ${ci.mensaje}`.trim() });
  const opciones = ci.data.privacy_level_options || [];
  const privacidad = opciones.includes('PUBLIC_TO_EVERYONE') ? 'PUBLIC_TO_EVERYONE' : opciones[0];
  if (!privacidad) return fin(false, { motivo: 'TikTok no devolvió opciones de privacidad para la cuenta' });
  cuerpo.post_info = { ...(cuerpo.post_info || {}), privacy_level: privacidad, brand_organic_toggle: true, brand_content_toggle: false };
}

const ini = await llamar(p.url, cuerpo);
const explicar = {
  access_token_invalid: 'el token de TikTok venció o no es válido (G54 tiene que renovarlo)',
  scope_not_authorized: 'la empresa no le dio a G54 el permiso de publicar en TikTok',
  url_ownership_unverified: 'el dominio de la imagen o el video no está verificado en la app de TikTok de G54',
  unaudited_client_can_only_post_to_private_accounts: 'la app de G54 todavía no pasó la auditoría de TikTok (usar modo borrador)',
  spam_risk_too_many_pending_share: 'hay 5 borradores sin publicar en la bandeja de TikTok de la empresa (TikTok no acepta más en 24 h)',
  spam_risk_too_many_posts: 'la cuenta llegó al límite diario de publicaciones de TikTok',
  app_version_check_failed: 'la app de TikTok del teléfono tiene que estar actualizada (31.8 o más)',
  rate_limit_exceeded: 'TikTok frenó por demasiadas llamadas; probar más tarde',
};
if (ini.code !== 'ok' || !ini.data.publish_id) {
  return fin(false, { motivo: `TikTok: ${explicar[ini.code] || ini.code} ${ini.mensaje ? '(' + ini.mensaje + ')' : ''}`.trim(), codigo: ini.code });
}
const publishId = ini.data.publish_id;

// Estado: en borrador termina en SEND_TO_USER_INBOX; en directo, en PUBLISH_COMPLETE. Se consulta hasta 6 veces, cada 5 s.
let estado = 'PROCESSING', detalle = '';
for (let i = 0; i < 6; i++) {
  await new Promise(r => setTimeout(r, 5000));
  const s = await llamar('https://open.tiktokapis.com/v2/post/publish/status/fetch/', { publish_id: publishId });
  if (s.code !== 'ok') { detalle = `${s.code} ${s.mensaje}`.trim(); continue; }
  estado = s.data.status || estado;
  if (estado === 'FAILED') { detalle = s.data.fail_reason || ''; break; }
  if (['SEND_TO_USER_INBOX', 'PUBLISH_COMPLETE'].includes(estado)) break;
}
if (estado === 'FAILED') return fin(false, { publish_id: publishId, estado, motivo: 'TikTok rechazó el contenido: ' + detalle });
const llego = ['SEND_TO_USER_INBOX', 'PUBLISH_COMPLETE'].includes(estado);
return fin(true, {
  publish_id: publishId,
  estado,
  confirmado: llego,
  nota: estado === 'SEND_TO_USER_INBOX' ? 'Enviado a la bandeja de TikTok: falta que alguien lo publique desde la app.'
      : estado === 'PUBLISH_COMPLETE' ? 'Publicado en TikTok.'
      : 'TikTok lo recibió y todavía lo está procesando (' + estado + ').',
});

// Si TikTok no recibió el post, avisa por correo (mismo destino que el Error Reporter). Si salió bien, no hace nada.
const r = $json;
if (r.ok) return [];
const asunto = `⚠️ G54: el post no llegó a TikTok (empresa ${r.company_id || '?'}, post ${r.post_id || '?'})`;
const html = `<div style="font-family:Arial,sans-serif;font-size:15px;color:#1d2420"><p>El envío a TikTok falló.</p>
<p>Empresa: ${r.company_id || '?'}<br>Post: ${r.post_id || '?'}<br>Modo: ${r.modo || '?'}<br>Ejecución: ${$execution.id}</p>
<p style="background:#fdecea;padding:12px;border-radius:6px">Motivo: ${String(r.motivo || '').slice(0, 500).replace(/[<>&]/g, '')}</p></div>`;
return [{ json: { asunto, html } }];
